// A search session stores a conversation's chat history, so Chat (Streaming)
// can pick up where the last message left off. Leave Search Session ID
// empty and the node creates one automatically, returning its ID in the
// response's search_session_id field — this code node just checks the
// workflow's static data for a session already mapped to this n8n chat
// session, so returning users continue their conversation instead of each
// message starting a fresh one.
//
// Static data is per-workflow, in-memory-backed storage that n8n persists to
// the database after each execution. It's fine for demos/small deployments,
// but it resets if you clear it manually, and it isn't shared across workers
// in a scaled/queue-mode setup. For production, replace this lookup/store
// pair with a real data store (a Data Table node, a database, Redis, etc.)
// keyed the same way.
const staticData = $getWorkflowStaticData('global');
staticData.searchSessions = staticData.searchSessions || {};

const n8nSessionId = $json.sessionId;
const existingSearchSessionId = staticData.searchSessions[n8nSessionId] || '';

return [
  {
    json: {
      ...$json,
      searchSessionId: existingSearchSessionId,
    },
  },
];

// Remembers the search session ID Chat (Streaming) just used — the one
// looked up above, or a freshly auto-created one on the first message — so
// the next message in this n8n chat session continues the same conversation.
const staticData = $getWorkflowStaticData('global');
staticData.searchSessions = staticData.searchSessions || {};

const triggerData = $('When chat message received').item.json;
staticData.searchSessions[triggerData.sessionId] = $json.search_session_id;

return [
  {
    json: {
      ...triggerData,
      searchSessionId: $json.search_session_id,
    },
  },
];
